prompt --application/pages/page_00004
begin
wwv_flow_imp_page.create_page(
 p_id=>4
,p_name=>'Document Preview'
,p_alias=>'DOCUMENT-PREVIEW'
,p_step_title=>'Document Preview'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#APP_FILES#pdf-lib.min.js',
''))
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Global variables',
'let globalWatermarkedPdfUrl = null;',
'let globalFileName = ''Document''; // Default name if not found in the database',
'',
'async function loadAndWatermarkPDF() {',
'    try {',
'        const ajaxUrl = `f?p=${apex.env.APP_ID}:${apex.env.APP_PAGE_ID}:${apex.env.APP_SESSION}:APPLICATION_PROCESS=GET_RAW_PDF`;',
'',
'        // Wait for the response from the database',
'        const response = await fetch(ajaxUrl);',
'        if (!response.ok) throw new Error("PDF fetch error");',
'        ',
'        // 1. EXTRACT FILE NAME FROM HEADER (sent by PL/SQL)',
'        const headerFileName = response.headers.get(''X-File-Name'');',
'        if (headerFileName) {',
'            globalFileName = headerFileName; // Saved in the global variable',
'        }',
'',
'        const pdfBytes = await response.arrayBuffer();',
'',
'        // pdf-lib logic',
'        const { PDFDocument, rgb, degrees, StandardFonts } = PDFLib; ',
'        const pdfDoc = await PDFDocument.load(pdfBytes);',
'',
'        const watermarkText = ''Confidential'';',
'        const fontSize = 60;',
'        const rotationAngle = 45;',
'',
'        const helveticaBoldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);',
'        const textWidth = helveticaBoldFont.widthOfTextAtSize(watermarkText, fontSize);',
'        const textHeight = helveticaBoldFont.heightAtSize(fontSize); ',
'        const textCenterOffsetY = textHeight / 3; ',
'',
'        const pages = pdfDoc.getPages();',
'        for (const page of pages) {',
'            const { width, height } = page.getSize();',
'            const pageCenterX = width / 2;',
'            const pageCenterY = height / 2;',
'',
'            const angleRad = rotationAngle * (Math.PI / 180); ',
'            const vecStartX = textWidth / 2;',
'            const vecStartY = textCenterOffsetY;',
'',
'            const rotatedOffsetX = vecStartX * Math.cos(angleRad) - vecStartY * Math.sin(angleRad);',
'            const rotatedOffsetY = vecStartX * Math.sin(angleRad) + vecStartY * Math.cos(angleRad);',
'',
'            const drawX = pageCenterX - rotatedOffsetX;',
'            const drawY = pageCenterY - rotatedOffsetY;',
'',
'            page.drawText(watermarkText, {',
'                x: drawX,',
'                y: drawY,',
'                size: fontSize,',
'                font: helveticaBoldFont,     ',
'                color: rgb(0.8, 0.8, 0.8),  ',
'                opacity: 0.5,               ',
'                rotate: degrees(rotationAngle),',
'            });',
'        }',
'',
'        const modifiedPdfBytes = await pdfDoc.save();',
'        const blob = new Blob([modifiedPdfBytes], { type: ''application/pdf'' });',
'        ',
'        globalWatermarkedPdfUrl = URL.createObjectURL(blob);',
'        document.getElementById(''pdfFrame'').src = globalWatermarkedPdfUrl;',
'',
'    } catch (err) {',
'        console.error(''Error: '', err);',
'        apex.message.alert(''Error loading PDF.'');',
'    }',
'}',
'',
'',
'function downloadWatermarkedPDF() {',
'    if (globalWatermarkedPdfUrl) {',
'        // 2. Get the name from the JS variable and remove ''.pdf''',
'        let originalFileName = globalFileName.replace(/\.pdf$/i, '''');',
'',
'        // 3. Create a new name by appending ''_watermark.pdf''',
'        let finalDownloadName = originalFileName + ''_watermark.pdf'';',
'',
'        const link = document.createElement(''a'');',
'        link.href = globalWatermarkedPdfUrl;',
'        link.download = finalDownloadName; ',
'        document.body.appendChild(link);',
'        link.click();',
'        document.body.removeChild(link);',
'    } else {',
'        // 4. Alert message for when the user clicks download before PDF is ready',
'        apex.message.alert(''PDF is still loading, please wait a moment.'');',
'    }',
'}',
'',
''))
,p_javascript_code_onload=>'loadAndWatermarkPDF();'
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
,p_created_on=>wwv_flow_imp.dz('20260911101500Z')
,p_last_updated_on=>wwv_flow_imp.dz('20260912085730Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_last_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
