);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(37339634226280973912)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_RAW_PDF'
,p_static_id=>'get-raw-pdf'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_mime_type VARCHAR2(100);',
'    l_file_name VARCHAR2(1000); -- Variable to fetch the file name',
'BEGIN',
'    -- Fetching both BLOB and File Name from the table in a single query',
'    SELECT document, mime_type, file_name',
'    INTO l_blob, l_mime_type, l_file_name',
'    FROM DEMO_DOCUMENT_WATERMARK',
'    WHERE document_id = :P4_DOCUMENT_ID;',
'',
'    -- Setting up HTTP Headers',
'    sys.htp.init;',
'    sys.owa_util.mime_header(nvl(l_mime_type, ''application/pdf''), FALSE);',
'    sys.htp.p(''Content-length: '' || sys.dbms_lob.getlength(l_blob));',
'    ',
'    -- THE MAGIC IS HERE: We are sending the file name in a custom header ''X-File-Name''',
'    sys.htp.p(''X-File-Name: '' || l_file_name);',
'    ',
'    sys.owa_util.http_header_close;',
'',
'    -- Return the BLOB data to the browser',
'    sys.wpg_docload.download_file(l_blob);',
'    apex_application.stop_apex_engine;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN NULL;',
'END;',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>37339634226280973912
,p_created_on=>wwv_flow_imp.dz('20260911101908Z')
,p_updated_on=>wwv_flow_imp.dz('20260911101908Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
